cat > /tmp/claude-0/-home-user-ainews/40ff19f3-e62d-505a-b532-83ab108306a1/scratchpad/inv.js <<'EOF'
const fs=require('fs');
const days=['2026-10-05','2026-10-06','2026-10-07','2026-10-08','2026-10-09','2026-10-10','2026-10-11','2026-10-12'];
for(const d of days){
  const p=`data/${d}.json`; if(!fs.existsSync(p)){console.log(`## ${d} MISSING`);continue;}
  const j=JSON.parse(fs.readFileSync(p,'utf8'));
  console.log(`\n## ${d} — ${j.title}`);
  for(const s of j.sections||[]){
    for(const it of s.items||[]){
      console.log(`- [${s.name.slice(0,14)}] ${it.headline}`);
      console.log(`    topics: ${(it.topics||[]).join(',')} | storylines: ${(it.storylines||[]).join(',')} | flags:${(it.flags||[]).join(',')} | impact:${it.impact||''}`);
      console.log(`    src: ${(it.sources||[]).map(x=>x.name+' '+x.url).join(' ;; ')}`);
    }
  }
}
EOF
node /tmp/claude-0/-home-user-ainews/40ff19f3-e62d-505a-b532-83ab108306a1/scratchpad/inv.js

cat > /tmp/claude-0/-home-user-ainews/40ff19f3-e62d-505a-b532-83ab108306a1/scratchpad/inv2.js <<'EOF'
const fs=require('fs');
const days=['2026-10-05','2026-10-06','2026-10-07','2026-10-08','2026-10-09','2026-10-10','2026-10-11','2026-10-12'];
const S={'Frontier models & labs':'FM','Research & papers':'RP','Security, misuse & threat intelligence':'SEC','Military, defense & geopolitics':'MIL','Health, science & medicine':'HSM','Policy, regulation & law':'POL','Compute, chips & infrastructure':'CMP','Deployment & impact':'DEP'};
for(const d of days){
  const j=JSON.parse(fs.readFileSync(`data/${d}.json`,'utf8'));
  console.log(`\n### ${d} | ${j.title}`);
  for(const s of j.sections||[]) for(const it of s.items||[])
    console.log(`${S[s.name]||s.name}| ${it.headline}  {${(it.topics||[]).join(',')}}${(it.storylines||[]).length?' SL:'+it.storylines.join(','):''}`);
}
EOF
